111	fn main() {
112	    tracing_subscriber::fmt()
113	        .with_env_filter(EnvFilter::from_default_env())
114	        .with_writer(std::io::stderr)
115	        .init();
116	
117	    let cli = Cli::parse();
118	
119	    let result = match cli.command {
120	        Commands::Init { global } => hooks::install(global),
121	        Commands::Uninit { global } => hooks::uninstall(global),
122	        Commands::Wrap { command } => wrap::execute(&command),
123	        Commands::Stats { json, days, waste } => stats::show(json, days, waste),
124	        Commands::Sync { once, api_url } => {
125	            let mut config = sync::SyncConfig::default();
126	            config.one_shot = once;
127	            if let Some(url) = api_url {
128	                config.api_url = url;
129	            }
130	            sync::run(config)
131	        }
132	        Commands::Login { auth_url } => auth::login(auth_url.as_deref()),
133	        Commands::Status => auth::status(),
134	        Commands::Logout => auth::logout(),
135	        Commands::Route { command, tokens, files } => handle_route(&command, tokens, &files),
136	
137	        Commands::Cache { action } => handle_cache(action),
138	        Commands::Hook { action } => handle_hook(action),
139	        Commands::Update => {
140	            println!("codeflow {}", env!("CARGO_PKG_VERSION"));
141	            println!("commit:  {}", option_env!("CODEFLOW_GIT_SHA").unwrap_or("dev"));
142	            println!("target:  {}", env!("TARGET"));
143	            println!();
144	            println!("Update: download latest from https://github.com/codeflow-dev/codeflow/releases");
145	            Ok(())
146	        }
147	    };
148	
149	    if let Err(e) = result {
150	        eprintln!("error: {:#}", e);
151	        std::process::exit(1);
152	    }
153	}
