425	fn open_session_log(
426	    session_id: &str,
427	) -> anyhow::Result<codeflow_core::session::SessionLog> {
428	    let db_path = paths::db_path();
429	    let data_dir = paths::data_dir();
430	    std::fs::create_dir_all(&data_dir)?;
431	    codeflow_core::session::SessionLog::open(&db_path, session_id)
432	}
