494	fn session_id() -> String {
495	    std::env::var("CLAUDE_SESSION_ID")
496	        .or_else(|_| std::env::var("CODEFLOW_SESSION_ID"))
497	        .unwrap_or_else(|_| {
498	            #[cfg(unix)]
499	            let ppid = unsafe { libc::getppid() } as u32;
500	            #[cfg(not(unix))]
501	            let ppid = std::process::id();
502	            format!("local-{}", ppid)
503	        })
504	}
