63	
64	func csvQuote(s string) string {
65		if len(s) == 0 {
66			return ""
67		}
68		needsQuote := false
69		for _, c := range s {
70			if c == ',' || c == '"' || c == '\n' || c == '\r' {
71				needsQuote = true
72				break
73			}
74		}
75		if !needsQuote {
76			return s
77		}
78		quoted := "\""
79		for _, c := range s {
80			if c == '"' {
81				quoted += "\"\""
82			} else {
83				quoted += string(c)
84			}
85		}
86		return quoted + "\""
87	}
