1	use anyhow::Result;
2	use rusqlite::{params, Connection};
3	use std::path::Path;
4	use std::time::{SystemTime, UNIX_EPOCH};
5	
6	const MAX_ENTRIES: usize = 10_000;
7	
8	pub struct DedupCache {
9	    conn: Connection,
10	    session_id: String,
11	}
12	
13	pub struct DedupResult {
14	    pub cache_hit: bool,
15	    pub content_hash: String,
16	    pub tokens_saved: u64,
17	    pub summary: Option<String>,
18	}
19	
20	impl DedupCache {
21	    pub fn open(db_path: &Path, session_id: &str) -> Result<Self> {
22	        let conn = Connection::open(db_path)?;
23	        conn.execute_batch(
24	            "PRAGMA journal_mode=WAL;
25	             PRAGMA synchronous=NORMAL;
26	             PRAGMA busy_timeout=5000;"
27	        )?;
28	        conn.execute_batch(
29	            "CREATE TABLE IF NOT EXISTS dedup_cache (
30	                content_hash TEXT PRIMARY KEY,
31	                file_path TEXT NOT NULL,
32	                mtime_ns INTEGER NOT NULL,
33	                byte_size INTEGER NOT NULL,
34	                token_count INTEGER NOT NULL,
35	                session_id TEXT NOT NULL,
36	                created_at INTEGER NOT NULL,
37	                last_hit_at INTEGER NOT NULL,
38	                hit_count INTEGER NOT NULL DEFAULT 1
39	            );"
40	        )?;
41	        Ok(Self {
42	            conn,
43	            session_id: session_id.to_string(),
44	        })
45	    }
46	
47	    pub fn lookup(
48	        &self,
49	        file_path: &str,
50	        current_mtime_ns: u64,
51	        content: &str,
52	    ) -> Result<DedupResult> {
53	        let hash = blake3::hash(content.as_bytes()).to_hex().to_string();
54	        let now = now_secs();
55	
56	        let row: Option<(i64, i64, String)> = self
57	            .conn
58	            .query_row(
59	                "SELECT token_count, mtime_ns, session_id FROM dedup_cache
60	                 WHERE content_hash = ?1",
61	                params![hash],
62	                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?)),
63	            )
64	            .optional()?;
65	
66	        match row {
67	            Some((token_count, stored_mtime, stored_session))
68	                if stored_mtime as u64 == current_mtime_ns
69	                    && stored_session == self.session_id =>
70	            {
71	                self.conn.execute(
72	                    "UPDATE dedup_cache SET last_hit_at = ?1, hit_count = hit_count + 1
73	                     WHERE content_hash = ?2",
74	                    params![now as i64, hash],
75	                )?;
76	                let summary = format!(
77	                    "File {} ({} tokens) read previously this session, unchanged.",
78	                    file_path, token_count
79	                );
80	                Ok(DedupResult {
81	                    cache_hit: true,
82	                    content_hash: hash,
83	                    tokens_saved: token_count as u64,
84	                    summary: Some(summary),
85	                })
86	            }
87	            _ => {
88	                let token_count = estimate_tokens(content);
89	                self.conn.execute(
90	                    "INSERT OR REPLACE INTO dedup_cache
91	                     (content_hash, file_path, mtime_ns, byte_size, token_count,
92	                      session_id, created_at, last_hit_at, hit_count)
93	                     VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?7, 1)",
94	                    params![
95	                        hash,
96	                        file_path,
97	                        current_mtime_ns as i64,
98	                        content.len() as i64,
99	                        token_count as i64,
100	                        self.session_id,
101	                        now as i64,
102	                    ],
103	                )?;
104	                self.evict_if_needed()?;
105	                Ok(DedupResult {
106	                    cache_hit: false,
107	                    content_hash: hash,
108	                    tokens_saved: 0,
109	                    summary: None,
110	                })
111	            }
112	        }
113	    }
114	
115	    pub fn invalidate_path(&self, file_path: &str) -> Result<u64> {
116	        let changes = self.conn.execute(
117	            "DELETE FROM dedup_cache WHERE file_path = ?1",
118	            params![file_path],
119	        )?;
120	        Ok(changes as u64)
121	    }
122	
123	    pub fn invalidate_session(&self) -> Result<u64> {
124	        let changes = self.conn.execute(
125	            "DELETE FROM dedup_cache WHERE session_id = ?1",
126	            params![self.session_id],
127	        )?;
128	        Ok(changes as u64)
129	    }
130	
131	    pub fn clear(&self) -> Result<u64> {
132	        let changes = self.conn.execute("DELETE FROM dedup_cache", [])?;
133	        Ok(changes as u64)
134	    }
135	
136	    pub fn entry_count(&self) -> Result<usize> {
137	        let count: i64 = self
138	            .conn
139	            .query_row("SELECT COUNT(*) FROM dedup_cache", [], |row| row.get(0))?;
140	        Ok(count as usize)
141	    }
142	
143	    fn evict_if_needed(&self) -> Result<()> {
144	        let count = self.entry_count()?;
145	        if count > MAX_ENTRIES {
146	            let to_remove = count - MAX_ENTRIES;
147	            self.conn.execute(
148	                "DELETE FROM dedup_cache WHERE content_hash IN (
149	                    SELECT content_hash FROM dedup_cache
150	                    ORDER BY last_hit_at ASC LIMIT ?1
151	                )",
152	                params![to_remove as i64],
153	            )?;
154	        }
155	        Ok(())
156	    }
157	}
158	
159	fn estimate_tokens(text: &str) -> usize {
160	    // ~4 chars per token is a reasonable approximation for English/code
161	    (text.len() + 3) / 4
162	}
163	
164	fn now_secs() -> u64 {
165	    SystemTime::now()
166	        .duration_since(UNIX_EPOCH)
167	        .unwrap_or_default()
168	        .as_secs()
169	}
170	
171	
172	
173	trait OptionalRow {
174	    fn optional(self) -> Result<Option<(i64, i64, String)>>;
175	}
176	
177	impl OptionalRow for rusqlite::Result<(i64, i64, String)> {
178	    fn optional(self) -> Result<Option<(i64, i64, String)>> {
179	        match self {
180	            Ok(row) => Ok(Some(row)),
181	            Err(rusqlite::Error::QueryReturnedNoRows) => Ok(None),
182	            Err(e) => Err(e.into()),
183	        }
184	    }
185	}
