88	fn show_waste(json: bool) -> Result<()> {
89	    let db_path = paths::db_path();
90	    let session_id = std::env::var("CLAUDE_SESSION_ID")
91	        .or_else(|_| std::env::var("CODEFLOW_SESSION_ID"))
92	        .unwrap_or_else(|_| {
93	            #[cfg(unix)]
94	            let ppid = unsafe { libc::getppid() } as u32;
95	            #[cfg(not(unix))]
96	            let ppid = std::process::id();
97	            format!("local-{}", ppid)
98	        });
99	
100	    let session_log = codeflow_core::session::SessionLog::open(&db_path, &session_id)?;
101	    let analyzer = codeflow_core::waste::WasteAnalyzer::new(&session_log);
102	    let report = analyzer.analyze()?;
103	
104	    if json {
105	        println!("{}", serde_json::to_string_pretty(&report)?);
106	        return Ok(());
107	    }
108	
109	    println!("CODEFLOW Waste Report");
110	    println!("═══════════════════════════════════════");
111	    println!();
112	
113	    if report.patterns.is_empty() {
114	        println!("  No waste patterns detected this session.");
115	        return Ok(());
116	    }
117	
118	    println!(
119	        "  Token waste detected: ~{} tokens ({:.1}% of session)",
120	        format_number(report.total_wasted_tokens),
121	        report.waste_percentage
122	    );
123	    println!();
124	
125	    let re_reads: Vec<_> = report
126	        .patterns
127	        .iter()
128	        .filter(|p| matches!(p, codeflow_core::waste::WastePattern::ReReadWaste { .. }))
129	        .collect();
130	    if !re_reads.is_empty() {
131	        println!("  Re-read waste ({} files):", re_reads.len());
132	        for p in &re_reads {
133	            if let codeflow_core::waste::WastePattern::ReReadWaste {
134	                file_path,
135	                read_count,
136	                redundant_count,
137	                tokens_wasted,
138	            } = p
139	            {
140	                println!(
141	                    "    {:<28} read {}x  →  {} redundant  (~{} tokens)",
142	                    truncate(file_path, 28),
143	                    read_count,
144	                    redundant_count,
145	                    format_number(*tokens_wasted)
146	                );
147	            }
148	        }
149	        println!();
150	    }
151	
152	    let redundant: Vec<_> = report
153	        .patterns
154	        .iter()
155	        .filter(|p| {
156	            matches!(
157	                p,
158	                codeflow_core::waste::WastePattern::RedundantCommand { .. }
159	            )
160	        })
161	        .collect();
162	    if !redundant.is_empty() {
163	        println!("  Redundant commands ({} patterns):", redundant.len());
164	        for p in &redundant {
165	            if let codeflow_core::waste::WastePattern::RedundantCommand {
166	                command_preview,
167	                run_count,
168	                redundant_count,
169	                tokens_wasted,
170	            } = p
171	            {
172	                println!(
173	                    "    {:<28} ran {}x  →  {} redundant  (~{} tokens)",
174	                    truncate(command_preview, 28),
175	                    run_count,
176	                    redundant_count,
177	                    format_number(*tokens_wasted)
178	                );
179	            }
180	        }
181	        println!();
182	    }
183	
184	    let failed: Vec<_> = report
185	        .patterns
186	        .iter()
187	        .filter(|p| matches!(p, codeflow_core::waste::WastePattern::FailedSearch { .. }))
188	        .collect();
189	    if !failed.is_empty() {
190	        println!("  Failed searches ({} patterns):", failed.len());
191	        for p in &failed {
192	            if let codeflow_core::waste::WastePattern::FailedSearch {
193	                pattern_preview,
194	                attempt_count,
195	            } = p
196	            {
197	                println!(
198	                    "    {}  →  0 results (tried {}x)",
199	                    truncate(pattern_preview, 40),
200	                    attempt_count
201	                );
202	            }
203	        }
204	        println!();
205	    }
206	
207	    let spam: Vec<_> = report
208	        .patterns
209	        .iter()
210	        .filter(|p| matches!(p, codeflow_core::waste::WastePattern::GlobSpam { .. }))
211	        .collect();
212	    if !spam.is_empty() {
213	        println!("  Glob spam ({} patterns):", spam.len());
214	        for p in &spam {
215	            if let codeflow_core::waste::WastePattern::GlobSpam {
216	                pattern_preview,
217	                run_count,
218	                redundant_count,
219	            } = p
220	            {
221	                println!(
222	                    "    {}  →  ran {}x ({} redundant)",
223	                    truncate(pattern_preview, 40),
224	                    run_count,
225	                    redundant_count
226	                );
227	            }
228	        }
229	        println!();
230	    }
231	
232	    let unused: Vec<_> = report
233	        .patterns
234	        .iter()
235	        .filter(|p| {
236	            matches!(
237	                p,
238	                codeflow_core::waste::WastePattern::LargeUnusedRead { .. }
239	            )
240	        })
241	        .collect();
242	    if !unused.is_empty() {
243	        println!("  Possibly unused large reads ({}):", unused.len());
244	        for p in &unused {
245	            if let codeflow_core::waste::WastePattern::LargeUnusedRead {
246	                file_path,
247	                token_count,
248	            } = p
249	            {
250	                println!(
251	                    "    {} (~{} tokens) read but not referenced later",
252	                    truncate(file_path, 30),
253	                    format_number(*token_count)
254	                );
255	            }
256	        }
257	        println!();
258	    }
259	
260	    println!("  Tip: CODEFLOW Read Dedup automatically prevents re-read waste.");
261	    println!("       Run `codeflow stats` to see your savings.");
262	
263	    Ok(())
264	}
