266	fn format_number(n: u64) -> String {
267	    if n >= 1_000_000 {
268	        format!("{:.1}M", n as f64 / 1_000_000.0)
269	    } else if n >= 1_000 {
270	        format!("{:.1}K", n as f64 / 1_000.0)
271	    } else {
272	        n.to_string()
273	    }
274	}
275	
276	fn truncate(s: &str, max: usize) -> String {
277	    if s.chars().count() > max {
278	        let truncated: String = s.chars().take(max - 1).collect();
279	        format!("{}…", truncated)
280	    } else {
281	        s.to_string()
282	    }
